using System;using System.IO;using System.Linq;using System.Text;using System.Data;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace MuEditorPhoenix {
 public static class CashInfo {
  public const string Guide="CASH SHOP — GUIA\r\n\r\n1. Abra o projeto com servidor, cliente e Item.xml corretos. Os cinco arquivos são um catálogo conjunto.\r\n2. CashShopProduct: ProductBase agrupa opções; ProductMain identifica a opção de compra. ItemCode identifica o item: seção × 512 + índice.\r\n3. Nome do item vem de Item.xml; nome da oferta vem de IBSProduct pelo par ProductBase/ProductMain. Eles podem ser diferentes. Duração no servidor é em segundos. Quantity não é estoque disponível; zero isolado não significa esgotado. Não troque todos os zeros por 1.\r\n4. Para um pacote simples, Sincronizar preço simples atualiza os quatro arquivos vinculados. Ofertas com variantes/bundles exigem revisão manual de cada vínculo e preço.\r\n5. Validar catálogo identifica ofertas sem pacote no servidor, vínculos ausentes e outros problemas. Não cria ofertas nem decide preços.\r\n6. Exportar cinco arquivos cria uma pasta separada, sem alterar as instalações. Server contém CashShopPackage.txt e CashShopProduct.txt para Data/CashShop. Client contém IBSCategory.txt, IBSPackage.txt e IBSProduct.txt para Data/InGameShopScript/<versão ativa>. Consulte DESTINOS.txt para os caminhos importados.\r\n7. Aplicar no projeto copia para os cinco arquivos importados, somente quando pertencem às pastas do projeto. Faz backup local e recusa arquivos alterados desde a leitura. Aplica apenas ao servidor escolhido; outro canal precisa ser aberto separadamente.\r\n8. Após aplicar: recarregue CashShop nos GameServers que usam esses arquivos e reabra o cliente. O editor não executa reload nem reinicia processos.\r\n9. Distribua somente os três IBS aos jogadores pelo publicador do seu launcher; ele deve gerar hashes e assinar o manifesto. Nunca envie os dois CashShop do servidor ao cliente. Exportar/aplicar não publica na web. O ZIP completo do cliente também deve ser atualizado pelo publicador.\r\n\r\nBackup local: %LOCALAPPDATA%/MUEditorPhoenix/CashShopBackups. Contém os originais e DESTINOS.txt; para restaurar, feche o cliente e recopie os originais aos respectivos destinos, depois recarregue CashShop.\r\n";
  public static string Item(Catalog items,DataRow row){int id;ItemDef item;if(!row.Table.Columns.Contains("ItemCode")||!int.TryParse(row["ItemCode"].ToString(),out id))return "";return items.Items.TryGetValue(id,out item)?item.Name:"Item.xml: não encontrado";}
  public static string Coordinate(DataRow row){int id;return row.Table.Columns.Contains("ItemCode")&&int.TryParse(row["ItemCode"].ToString(),out id)?(id/512)+":"+(id%512):"";}
  public static string Offer(CashCatalog cash,DataRow row){TextFile file;if(row.Table.Columns.Contains("Name"))return row["Name"].ToString();if(row.Table.Columns.Contains("ProductBase")&&row.Table.Columns.Contains("ProductMain")&&cash.Files.TryGetValue("IBSProduct.txt",out file))return string.Join(" / ",file.Rows().Where(x=>x["ProductID"].ToString()==row["ProductBase"].ToString()&&x["PriceID"].ToString()==row["ProductMain"].ToString()).Select(x=>x["Name"].ToString()).Distinct());if(row.Table.Columns.Contains("MainID")&&cash.Files.TryGetValue("IBSPackage.txt",out file))return string.Join(" / ",file.Rows().Where(x=>x["PackageID"].ToString()==row["MainID"].ToString()).Select(x=>x["Name"].ToString()).Distinct());return "";}
  public static string Duration(DataRow row){long seconds;if(!row.Table.Columns.Contains("Duration")||!long.TryParse(row["Duration"].ToString(),out seconds)||seconds<=0)return "";return seconds%86400==0?(seconds/86400)+" d":seconds%3600==0?(seconds/3600)+" h":seconds+" s";}
 }
 public static class CashDeployment {
  public static readonly Dictionary<string,int> Widths=new Dictionary<string,int>(StringComparer.OrdinalIgnoreCase){{"CashShopPackage.txt",28},{"CashShopProduct.txt",19},{"IBSCategory.txt",0},{"IBSPackage.txt",27},{"IBSProduct.txt",17}};
  public static Dictionary<string,byte[]> Prepare(CashCatalog cash){if(cash.Files.Count!=5||Widths.Keys.Any(k=>!cash.Files.ContainsKey(k)))throw new Exception("Importe os cinco arquivos do Cash Shop.");var output=new Dictionary<string,byte[]>(StringComparer.OrdinalIgnoreCase);foreach(var file in cash.Files.Values){if(Widths[file.Name]!=0&&file.Width!=Widths[file.Name])throw new Exception("Formato não suportado: "+file.Name);if(!file.At)foreach(var row in file.Rows())foreach(var value in row.ItemArray){uint number;if(!uint.TryParse(value.ToString(),out number))throw new Exception("Campo numérico inválido em "+file.Name+": "+value);}output[file.Name]=file.Export();}return output;}
  public static string Mapping(CashCatalog cash){return string.Join("\r\n",cash.Files.Values.Select(f=>(f.At?"CLIENTE":"SERVIDOR")+" — "+f.Name+"\r\n"+Path.GetFullPath(f.Source)+"\r\n"));}
  static bool Same(string a,string b){return string.Equals(Path.GetFullPath(a).TrimEnd(Path.DirectorySeparatorChar),Path.GetFullPath(b).TrimEnd(Path.DirectorySeparatorChar),StringComparison.OrdinalIgnoreCase);}
  public static void CheckTargets(CashCatalog cash,string server,string client){if(string.IsNullOrWhiteSpace(server)||string.IsNullOrWhiteSpace(client))throw new Exception("Escolha as pastas do projeto.");string clientParent=null;foreach(var file in cash.Files.Values){string parent=Path.GetDirectoryName(Path.GetFullPath(file.Source));if(!file.At){if(!Same(parent,Path.Combine(server,"Data","CashShop")))throw new Exception("Arquivo fora do servidor escolhido: "+file.Source);}else{string scripts=Path.Combine(client,"Data","InGameShopScript");if(!Same(Path.GetDirectoryName(parent),scripts))throw new Exception("Arquivo fora da versão do cliente escolhido: "+file.Source);if(clientParent!=null&&!Same(parent,clientParent))throw new Exception("Os três IBS precisam ser da mesma versão.");clientParent=parent;}for(var dir=new DirectoryInfo(parent);dir!=null;dir=dir.Parent)if((dir.Attributes&FileAttributes.ReparsePoint)!=0)throw new Exception("Destino com redirecionamento de pasta não suportado: "+parent);if((File.GetAttributes(file.Source)&FileAttributes.ReparsePoint)!=0)throw new Exception("Arquivo redirecionado não suportado.");if(!File.ReadAllBytes(file.Source).SequenceEqual(file.Original))throw new Exception("Arquivo mudou fora do editor. Reabra o projeto: "+file.Source);}}
  public static string Apply(CashCatalog cash,string server,string client,Dictionary<string,byte[]> output){return ApplyCore(cash,server,client,output,Guard.Atomic);}
  internal static string ApplyCore(CashCatalog cash,string server,string client,Dictionary<string,byte[]> output,Action<string,byte[]> write){var prepared=Prepare(cash);if(prepared.Any(p=>!output.ContainsKey(p.Key)||!output[p.Key].SequenceEqual(p.Value)))throw new Exception("Rascunho mudou; revise novamente.");CheckTargets(cash,server,client);string backup=Path.Combine(Guard.LocalData,"CashShopBackups",DateTime.UtcNow.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N"));foreach(var f in cash.Files.Values)Guard.Atomic(Path.Combine(backup,f.At?"Client":"Server",f.Name),f.Original);Guard.Atomic(Path.Combine(backup,"DESTINOS.txt"),Encoding.UTF8.GetBytes(Mapping(cash)));var changed=new List<TextFile>();try{foreach(var f in cash.Files.Values){if(!File.ReadAllBytes(f.Source).SequenceEqual(f.Original))throw new Exception("Arquivo alterado durante a aplicação: "+f.Source);if(output[f.Name].SequenceEqual(f.Original))continue;write(f.Source,output[f.Name]);changed.Add(f);}}catch(Exception ex){var failures=new List<string>();foreach(var f in changed.AsEnumerable().Reverse())try{if(!File.ReadAllBytes(f.Source).SequenceEqual(output[f.Name]))throw new Exception("mudança externa");Guard.Atomic(f.Source,f.Original);}catch{failures.Add(f.Source);}throw new Exception("Aplicação interrompida: "+ex.Message+"\r\nBackup: "+backup+"\r\n"+(failures.Count==0?"Gravações concluídas foram desfeitas.":"Restauração manual necessária: "+string.Join(", ",failures)));}foreach(var f in cash.Files.Values)f.Original=output[f.Name];return backup;}
 }
 public partial class PhoenixEditorForm {
  void CashPage(){var p=Page("Cash Shop");cashTabs.Dock=DockStyle.Fill;p.Controls.Add(cashTabs);var b=Bar();b.AutoSize=true;b.WrapContents=true;
   b.Controls.Add(Button("Importar arquivo",()=>{string f=PickFile("Cash Shop TXT|*.txt");if(f==null)return;if(!CashDeployment.Widths.ContainsKey(Path.GetFileName(f)))throw new Exception("Selecione um dos cinco arquivos do catálogo.");cash.Load(f);RefreshCash();}));
   b.Controls.Add(Button("Validar catálogo",()=>{EndCash();var errors=cash.Validate(catalog);Report("Diagnóstico Cash Shop",errors.Count==0?"Nenhuma divergência encontrada.":string.Join("\r\n",errors));}));
   b.Controls.Add(Button("Sincronizar preço simples",()=>{EndCash();string id=Ask("ID do pacote","PackageID / MainID");if(id==null)return;decimal price;if(!decimal.TryParse(Ask("Novo preço","Preço inteiro em moeda do catálogo"),out price))return;cash.SetPrice(id,price);cashTabs.Invalidate(true);status.Text="Preço alterado nos quatro arquivos. Exporte e revise antes de aplicar.";}));
   b.Controls.Add(Button("Exportar cinco arquivos",()=>ExportCash()));b.Controls.Add(Button("Aplicar no projeto",()=>ApplyCash()));b.Controls.Add(Button("Como editar / destinos",()=>Report("Guia Cash Shop",CashInfo.Guide+"\r\nARQUIVOS IMPORTADOS\r\n"+CashDeployment.Mapping(cash))));p.Controls.Add(b);
  }
  void EndCash(){foreach(TabPage page in cashTabs.TabPages)foreach(var g in page.Controls.OfType<DataGridView>()){g.EndEdit();if(g.DataSource!=null)BindingContext[g.DataSource].EndCurrentEdit();}}
  void RefreshCash(){cashTabs.TabPages.Clear();foreach(var file in cash.Files.Values){var page=new TabPage(file.Name);var g=Grid(true);g.DataSource=file.Table;g.ColumnHeadersHeightSizeMode=DataGridViewColumnHeadersHeightSizeMode.DisableResizing;g.ColumnHeadersHeight=36;g.AllowUserToAddRows=true;
    if(file.Table.Columns.Contains("ItemCode")){g.Columns.Add(new DataGridViewTextBoxColumn{Name="_ItemName",HeaderText="Item (Item.xml)",ReadOnly=true,AutoSizeMode=DataGridViewAutoSizeColumnMode.None,Width=220,DisplayIndex=0});g.Columns.Add(new DataGridViewTextBoxColumn{Name="_Coordinate",HeaderText="Section:Index",ReadOnly=true,AutoSizeMode=DataGridViewAutoSizeColumnMode.None,Width=125,DisplayIndex=1});}
    if(!file.Table.Columns.Contains("Name")&&(file.Table.Columns.Contains("ProductBase")||file.Table.Columns.Contains("MainID")))g.Columns.Add(new DataGridViewTextBoxColumn{Name="_Offer",HeaderText="Oferta (IBS)",ReadOnly=true,AutoSizeMode=DataGridViewAutoSizeColumnMode.None,Width=230,DisplayIndex=0});
    if(file.Table.Columns.Contains("Duration"))g.Columns.Add(new DataGridViewTextBoxColumn{Name="_Duration",HeaderText="Duração",ReadOnly=true,AutoSizeMode=DataGridViewAutoSizeColumnMode.None,Width=90,DisplayIndex=1});
    if(g.Columns.Contains("Quantity"))g.Columns["Quantity"].ToolTipText="Parâmetro de entrega; não é estoque. Zero isolado não significa esgotado. Consulte a duração e IBSProduct.";
    g.CellFormatting+=(sender,e)=>{if(e.RowIndex<0)return;var bound=g.Rows[e.RowIndex].DataBoundItem as DataRowView;if(bound==null)return;string col=g.Columns[e.ColumnIndex].Name;if(col=="_ItemName")e.Value=CashInfo.Item(catalog,bound.Row);else if(col=="_Coordinate")e.Value=CashInfo.Coordinate(bound.Row);else if(col=="_Offer")e.Value=CashInfo.Offer(cash,bound.Row);else if(col=="_Duration")e.Value=CashInfo.Duration(bound.Row);else return;e.FormattingApplied=true;};
    g.CellValueChanged+=(sender,e)=>g.Invalidate();page.Controls.Add(g);cashTabs.TabPages.Add(page);}}
  void ExportCash(){EndCash();var output=CashDeployment.Prepare(cash);string dest=PickFolder("Pasta separada para exportar cliente e servidor");if(dest==null)return;foreach(var file in cash.Files.Values)if(Path.GetFullPath(dest).Equals(Path.GetDirectoryName(Path.GetFullPath(file.Source)),StringComparison.OrdinalIgnoreCase))throw new Exception("Escolha uma pasta de saída separada.");foreach(var file in cash.Files.Values){string path=Path.Combine(dest,file.At?"Client":"Server",file.Name);if(cash.Files.Values.Any(f=>string.Equals(Path.GetFullPath(path),Path.GetFullPath(f.Source),StringComparison.OrdinalIgnoreCase)))throw new Exception("A exportação não pode sobrescrever um original importado.");}foreach(var file in cash.Files.Values)Guard.Atomic(Path.Combine(dest,file.At?"Client":"Server",file.Name),output[file.Name]);var diag=cash.Validate(catalog);Guard.Atomic(Path.Combine(dest,"DIAGNOSTICO.txt"),Encoding.UTF8.GetBytes(diag.Count==0?"Nenhuma divergência detectada.":string.Join("\r\n",diag)));Guard.Atomic(Path.Combine(dest,"LEIA-ME.txt"),Encoding.UTF8.GetBytes(CashInfo.Guide));Guard.Atomic(Path.Combine(dest,"DESTINOS.txt"),Encoding.UTF8.GetBytes(CashDeployment.Mapping(cash)));status.Text="Exportado sem aplicar: "+dest;}
  void ApplyCash(){EndCash();var output=CashDeployment.Prepare(cash);CashDeployment.CheckTargets(cash,server.Text,client.Text);var changed=cash.Files.Values.Where(f=>!f.Original.SequenceEqual(output[f.Name])).ToList();if(changed.Count==0){status.Text="Nenhuma alteração para aplicar.";return;}var diag=cash.Validate(catalog);string review="Alterados: "+string.Join(", ",changed.Select(f=>f.Name))+"\r\n\r\n"+CashDeployment.Mapping(cash)+"\r\n"+diag.Count+" divergência(s) no diagnóstico. Revise em Validar catálogo antes de continuar.\r\n\r\nFazer backup e aplicar neste projeto? Depois, recarregue CashShop e reabra o cliente. Não publica na web.";if(MessageBox.Show(this,review,"Aplicar Cash Shop",MessageBoxButtons.YesNo,MessageBoxIcon.Warning,MessageBoxDefaultButton.Button2)!=DialogResult.Yes)return;string backup=CashDeployment.Apply(cash,server.Text,client.Text,output);Report("Cash Shop aplicado","Aplicado aos cinco destinos importados.\r\nBackup: "+backup+"\r\nRecarregue CashShop no GameServer e reabra o cliente. Para os jogadores, publique os três IBS pelo launcher e atualize o ZIP completo.");}
 }
}
